const listDevices = `-- name: ListDevices :many

SELECT d.id, d.mac, d.identity_source, d.is_randomised, d.vendor, d.hostname, d.hostname_source, d.device_type, d.label, d.notes, d.group_name, d.is_ignored, d.first_seen, d.last_seen, d.device_class, d.device_class_confidence,
       CAST(COALESCE((SELECT GROUP_CONCAT(a.ip, ' ')
                      FROM addresses a
                      WHERE a.device_id = d.id
                        AND a.is_current = 1), '') AS TEXT) AS current_ips,
       CAST(COALESCE((SELECT GROUP_CONCAT(p.port, ' ')
                      FROM device_ports p
                      WHERE p.device_id = d.id
                        AND p.state = 'open'), '') AS TEXT) AS open_ports,
       CAST(COALESCE((SELECT GROUP_CONCAT(DISTINCT a.network_id)
                      FROM addresses a
                      WHERE a.device_id = d.id
                        AND a.is_current = 1
                        AND a.network_id IS NOT NULL), '') AS TEXT) AS network_ids
FROM devices d
WHERE (d.is_ignored = 0 OR d.is_ignored = ?1)
  AND (CAST(?2 AS TEXT) IS NULL OR d.group_name = CAST(?2 AS TEXT))
  AND (CAST(?3 AS INTEGER) IS NULL
    OR EXISTS (SELECT 1
               FROM addresses a
               WHERE a.device_id = d.id
                 AND a.is_current = 1
                 AND a.network_id = CAST(?3 AS INTEGER)))
  AND (CAST(?4 AS TEXT) IS NULL
    OR d.label LIKE '%' || CAST(?4 AS TEXT) || '%'
    OR d.hostname LIKE '%' || CAST(?4 AS TEXT) || '%'
    OR d.vendor LIKE '%' || CAST(?4 AS TEXT) || '%'
    OR d.mac LIKE '%' || CAST(?4 AS TEXT) || '%'
    OR EXISTS (SELECT 1
               FROM addresses a
               WHERE a.device_id = d.id
                 AND a.is_current = 1
                 AND a.ip LIKE '%' || CAST(?4 AS TEXT) || '%'))
ORDER BY d.last_seen DESC
`

type ListDevicesParams struct {
	IncludeIgnored bool           `json:"include_ignored"`
	GroupName      sql.NullString `json:"group_name"`
	NetworkID      sql.NullInt64  `json:"network_id"`
	Q              sql.NullString `json:"q"`
}

type ListDevicesRow struct {
	Device     Device `json:"device"`
	CurrentIps string `json:"current_ips"`
	OpenPorts  string `json:"open_ports"`
	NetworkIds string `json:"network_ids"`
}

// Reads.
// The current addresses come back on the device's own row rather than through a
// join, so one query answers the list. The open ports and the ids of the
// networks those addresses sit on ride along the same way, so a list can say
// what a device exposes and where it lives without a query per row.
// GROUP_CONCAT has no ordering worth relying on and the address column is TEXT,
// which sorts 192.0.2.9 after 192.0.2.100, so the caller splits and orders
// what it needs ordered.
//
// is_ignored compares against the argument rather than testing a flag: passing
// false leaves the clause admitting only unignored rows, and passing true makes
// the second half admit the rest.
//
//	SELECT d.id, d.mac, d.identity_source, d.is_randomised, d.vendor, d.hostname, d.hostname_source, d.device_type, d.label, d.notes, d.group_name, d.is_ignored, d.first_seen, d.last_seen, d.device_class, d.device_class_confidence,
//	       CAST(COALESCE((SELECT GROUP_CONCAT(a.ip, ' ')
//	                      FROM addresses a
//	                      WHERE a.device_id = d.id
//	                        AND a.is_current = 1), '') AS TEXT) AS current_ips,
//	       CAST(COALESCE((SELECT GROUP_CONCAT(p.port, ' ')
//	                      FROM device_ports p
//	                      WHERE p.device_id = d.id
//	                        AND p.state = 'open'), '') AS TEXT) AS open_ports,
//	       CAST(COALESCE((SELECT GROUP_CONCAT(DISTINCT a.network_id)
//	                      FROM addresses a
//	                      WHERE a.device_id = d.id
//	                        AND a.is_current = 1
//	                        AND a.network_id IS NOT NULL), '') AS TEXT) AS network_ids
//	FROM devices d
//	WHERE (d.is_ignored = 0 OR d.is_ignored = ?1)
//	  AND (CAST(?2 AS TEXT) IS NULL OR d.group_name = CAST(?2 AS TEXT))
//	  AND (CAST(?3 AS INTEGER) IS NULL
//	    OR EXISTS (SELECT 1
//	               FROM addresses a
//	               WHERE a.device_id = d.id
//	                 AND a.is_current = 1
//	                 AND a.network_id = CAST(?3 AS INTEGER)))
//	  AND (CAST(?4 AS TEXT) IS NULL
//	    OR d.label LIKE '%' || CAST(?4 AS TEXT) || '%'
//	    OR d.hostname LIKE '%' || CAST(?4 AS TEXT) || '%'
//	    OR d.vendor LIKE '%' || CAST(?4 AS TEXT) || '%'
//	    OR d.mac LIKE '%' || CAST(?4 AS TEXT) || '%'
//	    OR EXISTS (SELECT 1
//	               FROM addresses a
//	               WHERE a.device_id = d.id
//	                 AND a.is_current = 1
//	                 AND a.ip LIKE '%' || CAST(?4 AS TEXT) || '%'))
//	ORDER BY d.last_seen DESC
func (q *Queries) ListDevices(ctx context.Context, arg ListDevicesParams) ([]*ListDevicesRow, error) {
	rows, err := q.query(ctx, q.listDevicesStmt, listDevices,
		arg.IncludeIgnored,
		arg.GroupName,
		arg.NetworkID,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListDevicesRow
	for rows.Next() {
		var i ListDevicesRow
		if err := rows.Scan(
			&i.Device.ID,
			&i.Device.MAC,
			&i.Device.IdentitySource,
			&i.Device.IsRandomised,
			&i.Device.Vendor,
			&i.Device.Hostname,
			&i.Device.HostnameSource,
			&i.Device.DeviceType,
			&i.Device.Label,
			&i.Device.Notes,
			&i.Device.GroupName,
			&i.Device.IsIgnored,
			&i.Device.FirstSeen,
			&i.Device.LastSeen,
			&i.Device.DeviceClass,
			&i.Device.DeviceClassConfidence,
			&i.CurrentIps,
			&i.OpenPorts,
			&i.NetworkIds,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

