const updateDeviceCuration = `-- name: UpdateDeviceCuration :one

UPDATE devices
SET label       = ?1,
    notes       = ?2,
    group_name  = ?3,
    device_type = ?4,
    is_ignored  = ?5
WHERE id = ?6
RETURNING id, mac, identity_source, is_randomised, vendor, hostname, hostname_source, device_type, label, notes, group_name, is_ignored, first_seen, last_seen, device_class, device_class_confidence
`

type UpdateDeviceCurationParams struct {
	Label      sql.NullString `json:"label"`
	Notes      sql.NullString `json:"notes"`
	GroupName  sql.NullString `json:"group_name"`
	DeviceType sql.NullString `json:"device_type"`
	IsIgnored  bool           `json:"is_ignored"`
	ID         int64          `json:"id"`
}

// Writes.
// Every user-owned column is set rather than merged: the form submits all of
// them, so an omitted one means cleared, not unchanged.
//
//	UPDATE devices
//	SET label       = ?1,
//	    notes       = ?2,
//	    group_name  = ?3,
//	    device_type = ?4,
//	    is_ignored  = ?5
//	WHERE id = ?6
//	RETURNING id, mac, identity_source, is_randomised, vendor, hostname, hostname_source, device_type, label, notes, group_name, is_ignored, first_seen, last_seen, device_class, device_class_confidence
func (q *Queries) UpdateDeviceCuration(ctx context.Context, arg UpdateDeviceCurationParams) (*Device, error) {
	row := q.queryRow(ctx, q.updateDeviceCurationStmt, updateDeviceCuration,
		arg.Label,
		arg.Notes,
		arg.GroupName,
		arg.DeviceType,
		arg.IsIgnored,
		arg.ID,
	)
	var i Device
	err := row.Scan(
		&i.ID,
		&i.MAC,
		&i.IdentitySource,
		&i.IsRandomised,
		&i.Vendor,
		&i.Hostname,
		&i.HostnameSource,
		&i.DeviceType,
		&i.Label,
		&i.Notes,
		&i.GroupName,
		&i.IsIgnored,
		&i.FirstSeen,
		&i.LastSeen,
		&i.DeviceClass,
		&i.DeviceClassConfidence,
	)
	return &i, err
}

const upsertDeviceSource = `-- name: UpsertDeviceSource :exec
INSERT INTO device_sources (device_id, source_id, hostname, hostname_source, detail, first_seen, last_seen)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (device_id, source_id)
    DO UPDATE SET hostname        = CASE
                                        WHEN excluded.hostname IS NOT NULL THEN excluded.hostname
                                        ELSE device_sources.hostname END,
                  hostname_source = CASE
                                        WHEN excluded.hostname IS NOT NULL THEN excluded.hostname_source
                                        ELSE device_sources.hostname_source END,
                  detail          = excluded.detail,
                  last_seen       = excluded.last_seen
`

type UpsertDeviceSourceParams struct {
	DeviceID       int64                 `json:"device_id"`
	SourceID       int64                 `json:"source_id"`
	Hostname       sql.NullString        `json:"hostname"`
	HostnameSource dbtype.HostnameSource `json:"hostname_source"`
	Detail         sql.NullString        `json:"detail"`
	FirstSeen      dbtype.Time           `json:"first_seen"`
	LastSeen       dbtype.Time           `json:"last_seen"`
}

// Upserted rather than replaced, so first_seen survives every later reading.
//
// A name only moves when this source offers one: an empty reading leaves the
// last name it knew in place rather than clearing it. A sweep resolves a name
// per address, so a multi-homed host with a PTR on one interface and none on
// another would otherwise thrash its name every pass; and a device that stops
// answering has not been renamed, it has gone quiet. last_seen still ages, so
// how stale the kept name is stays visible. A different non-empty name, from
// this source or a higher one, still replaces it.
//
//	INSERT INTO device_sources (device_id, source_id, hostname, hostname_source, detail, first_seen, last_seen)
//	VALUES (?, ?, ?, ?, ?, ?, ?)
//	ON CONFLICT (device_id, source_id)
//	    DO UPDATE SET hostname        = CASE
//	                                        WHEN excluded.hostname IS NOT NULL THEN excluded.hostname
//	                                        ELSE device_sources.hostname END,
//	                  hostname_source = CASE
//	                                        WHEN excluded.hostname IS NOT NULL THEN excluded.hostname_source
//	                                        ELSE device_sources.hostname_source END,
//	                  detail          = excluded.detail,
//	                  last_seen       = excluded.last_seen
func (q *Queries) UpsertDeviceSource(ctx context.Context, arg UpsertDeviceSourceParams) error {
	_, err := q.exec(ctx, q.upsertDeviceSourceStmt, upsertDeviceSource,
		arg.DeviceID,
		arg.SourceID,
		arg.Hostname,
		arg.HostnameSource,
		arg.Detail,
		arg.FirstSeen,
		arg.LastSeen,
	)
	return err
}

